import sys
sys.path.insert(0,'submission')
from crosscheck import CrossCheck
T={'nodes':[{'id':0,'name':'A','external_capacity':100},{'id':1,'name':'B','external_capacity':100},{'id':2,'name':'C','external_capacity':100}],'links':[{'source':0,'target':1,'capacity':100},{'source':1,'target':2,'capacity':100},{'source':0,'target':2,'capacity':100}],'external_nodes':['A','B','C']}
S={'trials':1,'epsilon':0,'seed':1,'cutoff':[0,1],'bias':0,'tau':0,'gamma':[1,1],'cache_slots':2}
def make(reverse_obj=False, reverse_bundle=False):
 nm={0:'A',1:'B',2:'C'};paths={}
 pairs=[(0,1),(0,2),(1,0),(1,2),(2,0),(2,1)]
 for s,d in pairs:
  # direct endpoint paths for all except A-C maybe 2-hop; choose direct link
  if (min(s,d),max(s,d))==(0,1): base=[0,1]
  elif (min(s,d),max(s,d))==(1,2):base=[1,2]
  else:base=[0,2]
  if s>d:base=list(reversed(base))
  # second route via third node if available
  third=3-s-d if s in(0,1) and d in(0,1) else None
  entries=[]
  if third is not None:
   p2=[s,third,d];entries=[{'path':[nm[x] for x in base],'weight':400},{'path':[nm[x] for x in p2],'weight':600}]
  else:entries=[{'path':[nm[x] for x in base],'weight':1000}]
  if reverse_bundle:entries=list(reversed(entries))
  paths.setdefault(nm[s],{})[nm[d]]=entries
 if reverse_obj:
  new={}
  for k in reversed(list(paths)):new[k]=paths[k]
  paths=new
 return paths
ev=[{'op':'routes','label':'x','paths':make()},{'op':'repair','id':'a'},{'op':'routes','label':'y','paths':make(True,True)},{'op':'repair','id':'b'}]
for a in CrossCheck(T).replay(ev,S):print(a['op'],a.get('id'),a.get('cache_hit'))
